// Proactive Business English B2 · Syria Edition · Book 1 · Unit 8 — Answer Key (separate book)
const L = require('./lib');
const { p, h1, h2, h3, pb, sp, stage, box, dlg, table, C } = L;
const out = [];
const sample = (title, paras) => box(title, paras, 'FFFFFF', C.navy);
const note = t => p(`_${t}_`, { color: '595959' });

out.push(h1('Answer Key · Unit 8  Numbers in Prose'));
out.push(p('_Proactive Business English · B2 · Book 1 · Syria Edition_', { color: '7F7F7F' }));
out.push(box('How to use this key', [
  'Every task has an answer. Where the task is open, the key gives a **full sample answer**. Samples show one good B2 answer – learners\' own answers will be different and that is correct.',
  '⚠ **Unit 8 is the one unit in Book 1 where an answer can be arithmetically wrong, and that changes how it is taught.** **Everything in it can be checked with a pencil, and learners should be made to check it** — ⚠ **including the unit\'s own worked pages, which are correct and are meant to be verified rather than believed.**',
  '⚠ **Six things are taught and they build in one direction.** ⚠ **Period, basis and source (8.1) · the shape of three years (8.2) · per cent, points and the base (8.3) · the one-off (8.4) · precision (8.5) · the bridge (8.6).** **8.6 is impossible before 8.1, because a bridge is two figures each with a stated basis** — **and 8.4 is impossible before 8.2, because you cannot strip an item out of a shape you have not described.**',
  '⚠ **The one rule in the unit is in 8.5 and it should be said twice:** ⚠ **precision is a claim about method, and the claim has to be true.** **It is what joins the decimal on the forecast, the tenth of a debtor day, and the request that must not be hedged.**',
  '⚠ **8.7 reveals what the whole paper was for, and it should not be given away early.** **Mr Haddad can compute the figure he asks for from the aged list that was attached to the application.** ⚠ **He asks in order to find out, in the second and a half before the answer comes, whether the writer knew it, knew it was the worse number, and had decided to say it** — **which is the only part of a facility application that cannot be written down.**',
  '⚠ **Word counts.** Stage 6 asks for **80 words or more** and stage 7 for **200 to 240**. ⚠ **Cycle 7\'s exam task is Writing Part 2, a report, 120 to 140 words, 20 marks**; **the exam practice is Reading Part 4, multiple-choice cloze, fifteen gaps with four options, the second time in this book.**',
], C.grey, C.navy));

// ===================== 8.1 =====================
out.push(h2('8.1  A figure needs a basis'));
out.push(stage('1', 'Get ready'));
out.push(p('**a**  Open. ⚠ **Almost nobody gives the basis unprompted**, **and about half the room cannot name the source of a figure they use weekly** — **which is 8.1\'s finding arriving before the lesson.**'));
out.push(p('**b**  ⚠ **The second.** **It has a period (*the year to 31 December 2025*), a basis (*on the same basis as 2024*) and a source with a page (*page 4*)** — ⚠ **and the first has a number and nothing else, so a reader supplies the period and does not say which one he chose.**'));
out.push(stage('2', 'Listen and read'));
out.push(p('**a**  B   **b**  1 ⚠ **Its period, its basis, and where a reader can go and see it.**  2 ⚠ **She has used it in two papers, as 148.2 in one and 148 in the other, and the committee has both** — **and the same figure rounded two ways in two documents is read as two figures.**'));
out.push(p('⚠ **The *which last year* exchange is the one to dwell on, because it is not pedantry.** ⚠ **Sham Trading\'s year ends on 31 December and the bank\'s facility year runs to the end of June**, **so *last year* names two twelve-month periods that overlap by six months and differ by two seasons.** ⚠ **Put both year-ends on the board and ask the class which half of the trade falls in both.**'),);
out.push(p('⚠ **The page number is the cheapest instruction in the unit and the most resisted.** **Three characters.** ⚠ **The argument is in the track: a figure a reader can check in ten seconds is believed, and a figure he has to hunt for is read as a figure you hoped he would not look up** — **and the second half of that sentence is what learners have never considered.**'));
out.push(p('**Language box – Practise (sample, two of the four):**  _**1** The Ghouta run carried 3,140 cartons in the year to 31 December 2025, on the same basis as 2024 — the run sheets, totalled at appendix 1. **2** Stock was 19.4 million at 31 December 2025, valued at cost as in every prior year — audited accounts, page 5. ⚠ **Both have a period, a basis and a source, and neither is longer than twenty-two words.**_'));
out.push(stage('3', 'Practise – sample with role card 2'));
out.push(dlg(null, [
  ['A', 'Turnover was 148 million. I have it in the covering letter as well.'],
  ['B', 'As 148?'],
  ['A', 'As 148.2 in the letter. They are the same figure.'],
  ['B', 'They are the same figure and the committee has two documents.'],
  ['A', 'Nobody is going to read them side by side.'],
  ['B', 'The committee reads them side by side. That is what a committee is.'],
  ['A', 'Then I will change the letter to 148.'],
  ['B', 'Change both to the measured figure and decide the rounding once. 148.2 is what the accounts say.'],
  ['A', 'And if I had used 148 in three places?'],
  ['B', 'Then you change three places, and you write the rule down so there is never a fourth.'],
]));
out.push(note('This role card looks trivial and is the most frequently useful thing in the cycle, because learners do not believe the fault matters until they have been a reader. Put two of their own documents side by side and find the inconsistency — in the series\' own trial it was found in every learner\'s work within five minutes, usually between a monthly report and the e-mail that covered it. The remedy is not vigilance, which fails; it is a written rounding rule, which is what 8.5 builds. Say that now, so that 8.5 arrives as an answer to a problem the class has already met rather than as a convention.'));
out.push(stage('3R', 'Perform'));
out.push(p('**Listener task:** ⚠ **The figure with all three parts, and which of the speaker\'s years are on one basis.** **Expect the basis to be the part dropped** — ⚠ **learners will give period and source and treat the basis as obvious, which it is to them and to nobody else.**'));
out.push(stage('4', 'Your turn – sample table'));
out.push(table(['The figure', 'Its period', 'Its basis — and where it differs', 'Its source, with a page'], [
  ['**turnover 148.2 million**', '**year to 31 December 2025**', '⚠ **same as 2024; 2023 carries the Homs clearance of 6.1**', '**audited accounts, page 4**'],
  ['**debtor days 58**', '⚠ **at 31 December 2025, not an average of the year**', '⚠ **closing receivables over the year\'s sales, times 365**', '⚠ **my calculation, appendix 2** — **the accounts do not print it**'],
  ['**stock 19.4 million**', '**at 31 December 2025**', '**at cost, as in every prior year**', '**audited accounts, page 5**'],
  ['**the facility, 40 million**', '⚠ **twelve months from 1 July 2026** — **the bank\'s year, not ours**', '**not applicable; it is a request**', '**their form, box 3**'],
], [1.3, 1.5, 2.2, 1.6]));
out.push(stage('4R', 'Report – sample'));
out.push(p('_**The figure is 58 debtor days at the 31st of December 2025, on the basis of closing receivables over the year\'s sales times 365, which is not an average of the twelve months. The source is my own calculation at appendix 2, because the accounts do not print it.**_'));
out.push(p('⚠ **Both listener counts are worth collecting.** **How many figures had no page behind them: usually most.** ⚠ **How many had been quoted twice with two roundings: more than the room expects, and the way to find out is to make them look rather than remember.**'));
out.push(stage('5', 'Read'));
out.push(p('**1**  ⚠ **Debtor days** — **they are not in the accounts.** ⚠ **She had to choose the basis: closing receivables, or an average of the twelve months.** **Closing gives a higher number.** ⚠ **She used it because the committee will use it** — **and being corrected upwards later costs more than the three days ever would.**'));
out.push(p('**2**  ⚠ **Because the facility runs for the twelve months from 1 July 2026 and the trading years end in December**, ⚠ **so the three years in the paper and the twelve months the money is for do not overlap at all.** **And a committee that works that out for itself works out something else as well: that the writer did not.**'));
out.push(p('**3**  ⚠ **Because page 6 gives the margin for each year and does not give the three side by side** — **the comparison is hers.** ⚠ **A figure that is partly the document and partly your own arithmetic says so, and names both places.**'));
out.push(stage('6', 'Write with help – sample (149 words)'));
out.push(sample(null, [
  '**THE GHOUTA RUN — THE FIGURES AND WHERE THEY COME FROM. 10 May. L. Barakat. A working note.**',
  '**cartons carried, 2,840 / 3,010 / 3,140** | **years to 31 December** | ⚠ **one basis throughout** | **the run sheets, totalled at appendix 1**',
  '**deliveries made, 104 / 104 / 102** | **the same three years** | ⚠ **scheduled runs, not including the two special journeys of 2024** | **the day book**',
  '**cost per carton, 41 / 44 / 49 piastres** | **the same three years** | ⚠ **fuel, wages and the hire of a van where one was hired** | ⚠ **my calculation; it is not a figure anything prints**',
  '⚠ **The third row is the one to be careful with.** ⚠ **I have calculated it, and the basis I used** — **including hired vans rather than excluding them** — **gives a higher figure than the yard\'s own number.** **It is the harder basis and I have used it because a hired van is a cost of the run.**',
  '⚠ **And the second row excludes two journeys, which must be said rather than assumed.**',
]));
out.push(stage('6P', 'Check together – sample completed checklist'));
out.push(table(['Checklist', '✓ / ✗'], [
  ['A period on every figure, with a date and not *last year*', '**✓**'],
  ['A basis on every figure, and the one that differs named', '**✓** — **the two special journeys**'],
  ['A page, box or appendix on every source', '⚠ **✗** — **row 2 says *the day book* with no page**'],
  ['The calculated figure declared, with the basis chosen and why', '**✓** — **row 3**'],
  ['The figure on somebody else\'s period named as such', '⚠ **✗** — **the sample has no such figure, which is correct here and should be said rather than left blank**'],
], [5, 1]));
out.push(note('The last line is worth a word, because a blank in a checklist is ambiguous and learners treat it as a pass. Where a criterion does not apply — this note has no figure on another party\'s period — the right mark is a line through it with two words of explanation, not a tick and not a blank. It matters more than it sounds: a reviewer who meets five ticks cannot tell which criteria were tested, and the whole point of the band-4 slip is that the reviewer copies the line and names what they looked at.'));
out.push(stage('6R', 'Share'));
out.push(p('⚠ **The class asks what other basis was available** — **and where there was only one, the row is a document\'s figure after all and the declaration is unnecessary.** ⚠ **Expect two or three learners to discover that their *calculation* is simply a figure they have copied, which is a better outcome than a correct declaration.**'));
out.push(stage('7', 'Write freely – sample (229 words)'));
out.push(sample(null, [
  'Everybody here says that about a third of our business is export, and nobody can tell you what the third is a third of.',
  'The figure is used constantly. It is in the standing presentation, it was in the letter to the bank in 2024, and Mr Ayoub used it at the trade fair in September. Nobody has ever been asked what it means and I had not thought about it until this unit.',
  'There are at least three things it could be. A third of turnover, which would be about 49 million. A third of cartons, which is a different number because export cartons are heavier and dearer. Or a third of customers, which is six out of nineteen and is almost exactly a third, and I suspect is where the figure came from.',
  'Nobody has looked, because the figure has never had to be defended. It appears in documents where nobody checks and it has never appeared in one where somebody would.',
  'What it would take is an afternoon. The sales ledger is analysed by customer and the customers are either export or they are not, so turnover and cartons are both an hour\'s work.',
  'And the reason it matters is in this unit: a third of customers and a third of turnover are two different arguments, and the one we have been making for two years is whichever one the reader assumed.',
]));
out.push(stage('7P', 'Respond'));
out.push(p('⚠ **The *what period does it actually cover* question is the one that produces the surprise**, **and in the sample the answer is worse than a wrong period: the figure has no base at all and is probably a count of customers being used as a share of money.** ⚠ **That is 8.3 arriving early and is worth flagging for then.**'));
out.push(stage('7R', 'Share'));
out.push(p('⚠ **Expect nobody to be able to say what period the figure covers in all three texts, and in two of three for the figure to be two or three years old and repeated annually since.** ⚠ **The sentence to close on: a figure that has never had to be defended has never been checked, and it is usually the one that appears most often.**'));

// ===================== 8.2 =====================
out.push(pb());
out.push(h2('8.2  The trend and the blip'));
out.push(stage('1', 'Get ready'));
out.push(p('**a**  Open. ⚠ **The one-word answer is the teaching:** **most learners say *up* or *down*, which is a direction without a rate** — **and a direction without a rate is the half of 8.2 that a reader cannot use.**'));
out.push(p('**b**  ⚠ **The trend is the three years of turnover, 112, 131, 148** — **three points moving one way.** ⚠ **The blip is April 2025 at 9.4 against an average of 12.3** — **one point, with a cause, and one point can never be a trend.**'));
out.push(stage('2', 'Listen and read'));
out.push(p('**a**  B   **b**  1 ⚠ **Fifteen per cent a year compound.** **It is better because *seventeen then thirteen* invites the reader to extrapolate the thirteen** — ⚠ **he writes twelve in his own notes for next year and you never see him do it** — **and a single compound rate cannot be read as a deceleration.**  2 ⚠ **Name it, in the same sentence as the figure, with its cause attached.**'));
out.push(p('⚠ **The *two observations are not a trend* exchange is the intellectual centre of the cycle and it cuts both ways, which is what makes it worth teaching.** ⚠ **Seventeen to thirteen looks like a deceleration and is two steps; a deceleration needs four points and three years give two steps.** ⚠ **So the honest writer may neither claim the acceleration nor concede the slowdown** — **and the six words *two years, and not a direction* are what makes it possible to print both figures at all.**'));
out.push(p('⚠ **The blip argument is practical and should be made with the attachment in hand.** ⚠ **The monthly schedule goes in with the application.** **A blip the writer names is one sentence; a blip the committee finds in the schedule is the whole meeting** — ⚠ **and the committee will find it, because an unusual month is what an eye goes to in a column of twelve.**'));
out.push(p('**Language box – Practise (sample):**  _**The series:** cartons carried on the Ghouta run, 2,840, 3,010 and 3,140 over the three years to 31 December. ⚠ **The shape:** *rose from 2,840 to 3,140 over the three years, which is five per cent a year compound.* ⚠ **The blip:** *February was 198 cartons against a monthly average of 262, the hired van having failed to arrive on one of the four Mondays.*_'));
out.push(stage('3', 'Practise – sample with role card 2'));
out.push(dlg(null, [
  ['A', 'I have left April out. It is one month and it is not representative.'],
  ['B', 'Is the monthly schedule attached?'],
  ['A', 'Yes. Appendix 3.'],
  ['B', 'Then I am the committee. Twelve numbers, and one of them is 9.4 when the others are around 12. How long did that take me?'],
  ['A', 'Seconds.'],
  ['B', 'And now April is the only month I have an opinion about, and I have no explanation, and I am going to ask for one in a meeting.'],
  ['A', 'So I put it in.'],
  ['B', 'One sentence, with the eleven days in it. 9.4 against an average of 12.3, the plater out of service for eleven days.'],
  ['A', 'It draws attention to it.'],
  ['B', 'It draws attention to it for one sentence instead of for twenty minutes, and the attention it draws is to a press and not to you.'],
]));
out.push(note('The line to take out of this role card is the last one: naming a blip moves the reader\'s attention from the writer to the cause. Learners believe that mentioning a bad month is an admission and that omitting it is neutral. Omitting it is not neutral when the data is attached — it is the one choice that guarantees the bad month will be discussed without the writer present. Where a class resists, do the arithmetic of exposure with them: one sentence of about twenty words against an agenda item of twenty minutes, and the sentence is theirs to write.'));
out.push(stage('3R', 'Perform'));
out.push(p('**Listener task:** ⚠ **The direction-and-rate sentence and the blip sentence, with the words counted.** ⚠ **Both should come in under twenty-five words**, **and where either runs longer the usual cause is a reason being argued rather than stated.**'));
out.push(stage('4', 'Your turn – sample table'));
out.push(table(['The three figures', 'The direction and the rate, in one sentence', 'The worst point, with its cause'], [
  ['**2,840 / 3,010 / 3,140 cartons**', '⚠ *rose from 2,840 to 3,140 over the three years, which is five per cent a year compound*', '⚠ **February, 198 against an average of 262** — **the hired van failed on one Monday**'],
  ['**41 / 44 / 49 piastres a carton**', '⚠ *rose from 41 to 49 over the three years, which is nine per cent a year compound*', '⚠ **August, 56** — **two hired vans in one month**'],
  ['**104 / 104 / 102 deliveries**', '⚠ *flat at 104 for two years and 102 in 2025* — **and two of three points equal is not a decline**', '⚠ **none** — **no month is more than one delivery from its average**'],
], [1.5, 2.8, 2.3]));
out.push(stage('4R', 'Report – sample'));
out.push(p('_**It rose from 2,840 to 3,140 over the three years, which is five per cent a year compound. The worst point was February at 198 against an average of 262, because the hired van failed to arrive on one of the four Mondays.**_'));
out.push(p('⚠ **The second listener count is the useful one.** **How many series had fewer than four points: nearly all.** ⚠ **How many of those had been described as accelerating or decelerating anyway: almost all of them** — **and the phrase to hunt for on the board is *the rate of growth is slowing*, which is the commonest three-point conclusion in business English and needs four.**'));
out.push(stage('5', 'Read'));
out.push(p('**1**  ⚠ **Sentences 2, 3, 8 and 10.** ⚠ **2 stops the growth rate being read as flattered by the Homs one-off** — **and gives the higher figure, eighteen.** ⚠ **3 stops a deceleration being read from two steps.** ⚠ **8 stops the debtor-days series being read as a collapse in collection.** ⚠ **10 stops April being read as a trend.**'));
out.push(p('**2**  ⚠ **It gives the same series without the two export accounts: 46, 47 and 48.** ⚠ **What is left of the original series is still true** — **the receivables are what they are, and the facility is secured on them** — **but the lengthening is entirely the agreed sixty-day terms, and the collection performance has not moved.**'));
out.push(p('**3**  ⚠ **To bound every month that is not being discussed:** *no other month in the three years is more than eight per cent from its year\'s average.* ⚠ **It costs the writer the right to be silent about the other thirty-five months** — **the sentence can be checked against the schedule and must be true** — **and it buys the only thing worth having: April becomes the single exception rather than the first example.**'));
out.push(stage('6', 'Write with help – sample (153 words)'));
out.push(sample(null, [
  '**THE GHOUTA RUN, THREE YEARS. 12 May. L. Barakat. Eleven sentences.**',
  '**1**  _Cartons carried rose from 2,840 in the year to 31 December 2023 to 3,140 in 2025, which is five per cent a year compound._',
  '**2**  ⚠ _The 2024 figure includes 190 cartons on two special journeys for the Homs closure stock; excluding them, the three-year rate is seven per cent._',
  '**3**  _Growth was six per cent in 2024 and four per cent in 2025 — two years, and not a direction._',
  '**4**  ⚠ _Cost a carton rose from 41 to 49 piastres, which is nine per cent a year and faster than the cartons._',
  '**5**  ⚠ _The whole of that is van hire: on the runs where our own van was used, cost a carton was 41, 41 and 42._',
  '**6**  ⚠ _February 2025 carried 198 cartons against a monthly average of 262, a hired van having failed to arrive on one Monday._',
  '**7**  _No other month in the three years is more than nine per cent from its year\'s average._',
]));
out.push(stage('6P', 'Check together – sample completed checklist'));
out.push(table(['Checklist', '✓ / ✗'], [
  ['A direction and a rate in the first sentence', '**✓**'],
  ['The one-off named, and the rate restated without it', '**✓** — **the two special journeys, and seven per cent**'],
  ['Two steps labelled *two years, and not a direction*', '**✓**'],
  ['The series that moved against you, named by you', '⚠ **✓** — **sentence 4, cost a carton, and sentence 5 gives its cause**'],
  ['A bound on every point you are not discussing', '**✓** — **sentence 7**'],
], [5, 1]));
out.push(note('This is the one stage in Unit 8 where a class usually scores well, and the reason is worth understanding: the frame is doing the work. Do not leave it there. Take the completed sentences away and ask for the same eleven from memory, and the sentences that disappear first are 3, 5 and 7 — the two that refuse a conclusion and the one that bounds the rest. Those three are the unit, and they are the ones a learner will not write unprompted in six months. The remedy is to name them as a set: the refusal, the cause, and the bound.'));
out.push(stage('6R', 'Share'));
out.push(p('⚠ **The class asks whether the cause is in the same sentence as the adverse series, and who would have found it first.** ⚠ **Where a learner has put the cause in a later sentence, make them read the two sentences in the order a reader meets them** — **the adverse figure alone, then the explanation** — **and the three seconds in between are the whole argument for one sentence.**'));
out.push(stage('7', 'Write freely – sample (230 words)'));
out.push(sample(null, [
  'The Saturday trial got nineteen orders against the thirty we needed, and that one Saturday has been treated as a finding about Saturdays for two years.',
  'The figure was nineteen. The average Thursday takes about twenty-six orders, so nineteen is low, and it was one day.',
  'What caused it, as far as anybody now remembers, was that the trial Saturday was the second day of a holiday weekend and half the Baghdad Street counter\'s regulars were away. Nobody wrote that down at the time. It is in nobody\'s notes and I only have it because Nadia remembers the week.',
  'Who treated it as a trend was all of us, including me. The paper that went to Mr Ayoub said the Saturday trial did not work. One day, one number, no cause, and a conclusion in the past tense.',
  'What was decided because of it is that we do not open on Saturdays, which has now been the position for two years and has never been revisited. Four Saturdays would have cost us about forty thousand in wages and would have given four points instead of one.',
  'And the thing that makes this hard to defend is that the figure was not wrong and nobody misrepresented anything. Nineteen is nineteen. What was wrong was that one point was read as a direction, and nobody wrote the sentence that would have stopped it.',
]));
out.push(stage('7P', 'Respond'));
out.push(p('⚠ **The *how many points were there* question is usually answered *one*, and the sample is the honest version of that: nobody lied, the figure was right, and one point was read as a direction.** ⚠ **The follow-up worth asking is what four points would have cost** — **in the sample, forty thousand and four Saturdays** — **because a class that can price a trend stops accepting one.**'));
out.push(stage('7R', 'Share'));
out.push(p('⚠ **Expect all three decisions to rest on fewer than four points, and in two of three the figure to have returned to its average the following month.** ⚠ **The sentence to close on: a decision taken on one point is almost never revisited, because the point that would revisit it is never collected.**'));

// ===================== 8.3 =====================
out.push(pb());
out.push(h2('8.3  Per cent, points and the base'));
out.push(stage('1', 'Get ready'));
out.push(p('**a**  Open. ⚠ **The second half is the test and about half the room cannot answer it**, **which is the cycle\'s whole subject: a percentage is a fraction and a fraction has a denominator, and the denominator is the thing nobody says.**'));
out.push(p('**b**  ⚠ **The second.** ⚠ **The margin is itself a percentage, so a movement in it is measured in percentage points.** ⚠ **A fall of 1.6 per cent from 21.4 is a fall of 0.34, which would take the margin to 21.06** — **and that is what the first sentence says, whatever it means.**'));
out.push(stage('2', 'Listen and read'));
out.push(p('**a**  B   **b**  1 ⚠ **Three hundred per cent growth from two is eight, not six.** **From two to six is two hundred per cent, or trebled.**  2 ⚠ **The two numbers, with no percentage at all** — *from two customers to six* — **four words, and nobody can argue with it.**'));
out.push(p('⚠ **Do the arithmetic on the board, both ways, because the class will not believe the first one.** ⚠ **Three hundred per cent of two is six; six added to the original two is eight.** **Two to six is an increase of four, and four over two is two hundred per cent.** ⚠ **Then ask which of the two sentences a learner would have written, and most will admit to the wrong one.**'));
out.push(p('⚠ **The points-against-per-cent rule is the one piece of pure form in Unit 8 and it must be drilled rather than explained.** ⚠ **A movement in a quantity is in per cent; a movement in a percentage is in percentage points.** ⚠ **And the reason it matters more than its size suggests is Bassel\'s:** **a bank\'s entire trade is the difference between a rate and a movement in a rate, and it cannot tell whether you do not know or you are hoping.**'));
out.push(p('⚠ **The last exchange is the one that recurs in every learner\'s workplace.** ⚠ *Nine per cent of which sales?* **Nine per cent of turnover is 13.3 million; nine per cent of cartons is a different number and a different argument** — **and the figure in the paper is whichever one the reader assumed.**'));
out.push(p('**Language box – Practise (sample, four repaired):**  _**1** *the margin fell 1.6 per cent* → ⚠ *fell 1.6 percentage points, from 21.4 to 19.8 per cent*.  **2** *the account grew three hundred per cent* → ⚠ *from two customers to six*.  **3** *the run is nine per cent of sales* → ⚠ *6.2 per cent of turnover, and 9.1 per cent of cartons*.  **4** *debtor days are 58* → ⚠ *58 debtor days, of which 60 days are agreed terms on the two export accounts*._'));
out.push(stage('3', 'Practise – sample with role card 2'));
out.push(dlg(null, [
  ['A', 'The Ghouta run is nine per cent of sales. It is in the standing presentation.'],
  ['B', 'Nine per cent of which sales?'],
  ['A', 'Of sales. Of turnover.'],
  ['B', 'Where did the nine come from?'],
  ['A', 'It was calculated in 2023. From the run sheets.'],
  ['B', 'The run sheets are in cartons.'],
  ['A', '…So it is nine per cent of cartons.'],
  ['B', 'And on turnover?'],
  ['A', 'Six point two, because the run carries the cheaper lines.'],
  ['B', 'So for two years the presentation has overstated the run by about a half, and nobody did anything wrong at any point.'],
]));
out.push(note('That last line is the one to leave with the class, because it is what makes this fault survive. There is no moment of dishonesty to find: somebody calculated a correct figure on a correct base, stated the base once, and everybody afterwards repeated the number without it. No document records a change because nothing changed — a base was omitted, repeatedly, and the omission drifted. The practical instruction follows: a percentage travels with its base or it does not travel. Where a learner has a figure in a standing presentation, that is the document to check first, because a standing document is repeated most and checked least.'));
out.push(stage('3R', 'Perform'));
out.push(p('**Listener task:** ⚠ **The small-base figure as two numbers, the margin movement in points, and the base of the third percentage.** ⚠ **The third is the one learners cannot supply from the performance alone**, **which is the point: a percentage whose base is not said is not recoverable by a listener.**'));
out.push(stage('4', 'Your turn – sample table'));
out.push(table(['The percentage as it is used', 'What the hundred is', 'Per cent or points?', 'How I will write it'], [
  ['**the run is nine per cent of sales**', '⚠ **cartons, not turnover** — **it was calculated on the run sheets**', '**per cent**', '⚠ *6.2 per cent of turnover, and 9.1 per cent of cartons*'],
  ['**the margin fell 1.6 per cent**', '**the margin itself**', '⚠ **points**', '⚠ *fell 1.6 percentage points, from 21.4 to 19.8 per cent*'],
  ['**export is a third of the business**', '⚠ **nobody knows** — **probably customers, six of nineteen**', '**per cent**', '⚠ *six of our nineteen customers; on turnover, 33 per cent is not supported*'],
  ['**wastage is up two per cent**', '⚠ **unstated** — **two per cent of wastage, or two points of the wastage rate**', '⚠ **points, if it is a rate**', '⚠ *the wastage rate rose 0.2 of a point, from 1.1 to 1.3 per cent*'],
], [1.8, 1.5, 1.1, 2.1]));
out.push(stage('4R', 'Report – sample'));
out.push(p('_**I use *nine per cent of sales*. The hundred is cartons, not turnover, because it was calculated from the run sheets. It is a movement in nothing, it is a share, so it is per cent. And I will write it as 6.2 per cent of turnover and 9.1 per cent of cartons.**_'));
out.push(p('⚠ **The second listener count is the one that produces silence.** **How many percentages were calculated on one base and are now quoted on another: at least one in most rooms, and nobody has ever found it before** — ⚠ **because the fault leaves no trace in any document and can only be found by asking where the number came from.**'));
out.push(stage('5', 'Read'));
out.push(p('**1**  ⚠ **A movement in a percentage given in per cent.** ⚠ **1.6 per cent of 21.4 is 0.34, so the sentence says the margin went from 21.4 to 21.06** — **which is not what happened and is not what anybody meant.**'));
out.push(p('**2**  ⚠ **Nine per cent of cartons became *nine per cent of sales* in a letter in 2023 and has been repeated eleven times since, including twice to the bank.** ⚠ **The true figure on turnover is 6.2 per cent**, **so the importance of the run has been overstated by about a half for two years.**'));
out.push(p('**3**  ⚠ **Because debtor days are the series the facility is secured on**, ⚠ **and *58* reads as sixty days of lateness to three readers in four** — **when sixty of those days are agreed terms on the two export accounts.** **The clause that fixes it is eleven words and belongs in the same sentence as the figure.**'));
out.push(stage('6', 'Write with help – sample (151 words)'));
out.push(sample(null, [
  '**FOUR PERCENTAGES IN THE STANDING PRESENTATION. 14 May. L. Barakat. Working note.**',
  '**the run is nine per cent of sales** | ⚠ **no base. Nine per cent was calculated on cartons in 2023 and has been repeated since as though it were turnover.** | ⚠ *6.2 per cent of turnover, and 9.1 per cent of cartons*',
  '**export is a third of the business** | ⚠ **no base at all; it is probably six customers of nineteen, which is a count and not a share of money** | ⚠ *six of nineteen customers; on turnover, export is 28 per cent*',
  '**wastage is up two per cent** | ⚠ **a rate moved, so it is points** | ⚠ *the wastage rate rose 0.2 of a point, from 1.1 to 1.3 per cent*',
  '**the counter is four times busier on Thursdays** | ⚠ **four times than what — than Monday, or than the average?** | ⚠ *Thursday takes 26 orders against a daily average of 11*',
  '⚠ **The first row is the one that has done real damage.** ⚠ **It has been repeated for two years, including to the bank** — **and the true figure is 6.2.**',
  '⚠ **Nobody did it deliberately. A base stated once and then dropped drifts to whichever base the next writer assumes.**',
]));
out.push(stage('6P', 'Check together – sample completed checklist'));
out.push(table(['Checklist', '✓ / ✗'], [
  ['The arithmetic of the drafted sentence computed, not the intention', '⚠ **✗** — **no row shows what the drafted sentence actually says; the second column names the fault instead**'],
  ['A movement in a percentage written in points', '**✓** — **row 3**'],
  ['A small-base percentage replaced by two numbers', '**✓** — **rows 2 and 4**'],
  ['The drifted figure, with the number of repetitions', '⚠ **✗** — **_two years_ is a duration, not a count; the instruction is a number**'],
  ['A clause stopping a ratio from reading as a quantity', '⚠ **✗** — **there is no ratio in this note, and the criterion should be struck through rather than failed**'],
], [5, 1]));
out.push(note('Two of those three failures are instructive and one is a marking question. The first — computing what the drafted sentence actually says — is the single most valuable habit in this cycle and the hardest to instil, because a writer reads their own sentence for its intention. Make the class do the arithmetic of the wrong version aloud: 1.6 per cent of 21.4 is 0.34, so the margin went to 21.06. The fourth is simple and worth insisting on: "repeated for two years" cannot be checked and "repeated eleven times, twice to the bank" can, and the difference matters because a reader needs to know whether he is being corrected on a figure he has already been given. The fifth is the marking question from 8.1 again: a criterion that does not apply is struck through with two words, never ticked and never left blank.'));
out.push(stage('6R', 'Share'));
out.push(p('⚠ **The class asks how many times the drifted figure has been repeated** — **and where nobody knows, the note says *at least*, followed by the number anybody can evidence.** ⚠ **_At least eleven_ is a defensible sentence and *about a dozen* is not.**'));
out.push(stage('7', 'Write freely – sample (227 words)'));
out.push(sample(null, [
  'For three years this company has told people that it supplies a fifth of the dried-goods trade in this quarter of the city, and I have not been able to find out what the fifth is a fifth of.',
  'It came from a count. In 2022 somebody walked the quarter and counted the shops that stocked our lines against the shops that did not, and the answer was about one in five. That is a share of outlets.',
  'What it has been used to argue is a share of money. It was in the letter to the bank in 2024 under the heading of market position, and it was in the Baghdad Street counter paper as a reason the counter would fill quickly, which it did not.',
  'On outlets, one in five is still roughly right: I walked it again in April and counted twenty-two of a hundred and three.',
  'On money, nobody can calculate it at all, because we do not know what the other hundred and one shops sell. The figure does not exist on that base and never did.',
  'What the difference would have changed is the Baghdad Street paper. A fifth of the outlets tells you nothing about how fast a new counter fills. A fifth of the money would have, and we did not have it, and we wrote as though we did.',
]));
out.push(stage('7P', 'Respond'));
out.push(p('⚠ **The *which base was it first calculated on* question is answerable in most texts and the answer is usually a count of things**, **used later as a share of money.** ⚠ **That is the single commonest base-drift in business writing and it is worth naming as a pattern: counts drift into values, because both are fractions and only one of them is usually available.**'));
out.push(stage('7R', 'Share'));
out.push(p('⚠ **Expect two of three figures to have been used to argue for something, and the decision to have been taken on the base the writer assumed.** ⚠ **The sentence to close on: a figure that exists on one base and is used on another is not an error anybody made, and it cannot be found in any document** — **only by asking who first calculated it and from what.**'));

// ===================== 8.4 =====================
out.push(pb());
out.push(h2('8.4  Stripping out the one-off'));
out.push(stage('1', 'Get ready'));
out.push(p('**a**  Open. ⚠ **Ask for the figure without the item as a number, not as a direction** — **a learner who says *it would be better* has not done the arithmetic, and the arithmetic is the whole task.**'));
out.push(p('**b**  ⚠ **The second.** **The first is true and will be read as the whole truth until somebody finds the clearance in the base year** — ⚠ **and the second gives both figures, which leaves nothing to allege in either direction.**'));
out.push(stage('2', 'Listen and read'));
out.push(p('**a**  B   **b**  1 ⚠ **It goes from fifteen per cent a year to eighteen** — **so the honest figure is the better one.**  2 ⚠ **Two questions, and both must be answered yes: did it happen for a reason that has gone, and will it not happen again?**'));
out.push(p('⚠ **The opening is the one that changes behaviour, and it is counter-intuitive enough to be worth reading twice.** ⚠ **Nour had decided not to mention the Homs clearance precisely BECAUSE mentioning it helps her** — **an adjustment that flatters you looks arranged.** ⚠ **Mr Attar\'s answer is the cycle: not mentioning it is also an arrangement, and the only version with nothing left to allege is both figures with their labels.**'));
out.push(p('⚠ **The plater exchange is the test applied to something that fails it, and the distinction is the most useful one in Unit 8.** ⚠ **A press nine years old that has broken twice will break again at some rate.** ⚠ **That is a frequency, not an event** — **and a frequency stripped out of a figure is the commonest dishonest adjustment there is.** **It stays in the figure and gets a sentence.**'));
out.push(p('⚠ **And the last line is worth a minute of arithmetic:** ⚠ **a blip is a thing you explain and a one-off is a thing you remove, and the difference between those two words in this paper is about four million.** **Ask the class to work out why** — **eleven days of a 12.3-million month is about 4.5, and removing it would lift the year by that much.**'));
out.push(p('**Language box – Practise (sample, three items tested):**  _**1 The two special journeys for the Homs closure stock, 190 cartons.** ⚠ **Reason gone: yes, the store closed in 2021. Will not recur: yes.** → ⚠ **removed and declared; the rate goes from five per cent to seven.**  **2 The hired van failing in February.** ⚠ **Reason gone: no. Will not recur: no — we hire a van about nine times a year.** → **kept, and explained.**  **3 The August fuel price.** ⚠ **Reason gone: no. Will not recur: no.** → **kept; a price is never a one-off.**_'));
out.push(stage('3', 'Practise – sample with role card 2'));
out.push(dlg(null, [
  ['A', 'I want to take the February van failure out. It is one Monday in three years.'],
  ['B', 'How often do you hire a van?'],
  ['A', 'Nine or ten times a year.'],
  ['B', 'And how often has a hired van not arrived?'],
  ['A', 'Twice. February, and once in 2023.'],
  ['B', 'So it happens about once in fifteen hires. That is a rate.'],
  ['A', 'It is a very low rate.'],
  ['B', 'It is a low rate and it is still a rate, and a rate stripped out of a figure is an adjustment that assumes the thing will never happen again. Will it never happen again?'],
  ['A', 'No. We will hire a van next month.'],
  ['B', 'Then it stays in, and it gets a sentence. The sentence is cheaper than the argument you would have about the adjustment.'],
]));
out.push(note('The useful move here is to ask for the denominator, which turns a judgement into arithmetic. "One Monday in three years" sounds like an event; "twice in about thirty hires" is a rate, and the second phrasing is the same facts counted properly. Learners who learn to ask how many opportunities there were stop classifying frequencies as events, and the question generalises: a machine that has broken twice in nine years has a rate, a driver who has been ill twice has a rate, and a customer who has paid late three times out of forty has a rate. Only a thing whose occasion no longer exists — a store that has closed, a contract that has ended, a building that has been sold — is a one-off.'));
out.push(stage('3R', 'Perform'));
out.push(p('**Listener task:** ⚠ **The two figures with their labels, and the item that was kept with the two questions that kept it.** ⚠ **The second answer is the one to insist on being a sentence rather than a word**: **_no, because we hire a van nine times a year_ is the answer; *no* is not.**'));
out.push(stage('4', 'Your turn – sample table'));
out.push(table(['The item', 'A reason that has gone?', 'Will it not happen again?', 'Remove and declare, or keep and explain'], [
  ['**the two special journeys, 190 cartons**', '⚠ **yes** — **the Homs store closed in 2021**', '⚠ **yes** — **there is no Homs stock left**', '⚠ **removed and declared: five per cent becomes seven**'],
  ['**the February van failure**', '⚠ **no** — **we hire about nine times a year**', '⚠ **no** — **twice in thirty hires is a rate**', '⚠ **kept and explained in one sentence**'],
  ['**the August fuel price**', '⚠ **no**', '⚠ **no** — **a price is never a one-off**', '**kept; and it is the cause of row 4 of the cost series**'],
  ['**the 2024 holiday week**', '⚠ **no** — **there is one every year**', '⚠ **no**', '⚠ **kept, and named as a seasonal pattern rather than an item**'],
], [1.6, 1.4, 1.4, 2.1]));
out.push(stage('4R', 'Report – sample'));
out.push(p('_**The item is the two special journeys for the Homs stock. They happened because the store closed, which has happened and is finished. They will not happen again, because there is no Homs stock left. So I will remove them and declare it, and the two figures are five per cent a year and seven.**_'));
out.push(p('⚠ **The second listener count is the one that lands.** **How many items were frequencies rather than one-offs: usually three of four.** ⚠ **How many of those had already been stripped out of a figure by somebody: at least one in most rooms** — **and that adjustment is almost always undeclared, which is why nobody can now withdraw it.**'));
out.push(stage('5', 'Read'));
out.push(p('**1**  ⚠ **One of the four passed: the Homs clearance.** ⚠ **Stating the proportion tells a reader that both questions were applied to everything and not only to the items the writer wanted out** — **and three failures out of four is the normal proportion, because everything in a set of figures looks unusual when you are looking for reasons.**'));
out.push(p('**2**  ⚠ **The Baghdad Street opening margin.** **It passes the first question** — **a new counter trades thin while it fills, and that reason has gone** — ⚠ **and fails the second, because the firm intends to open more counters.** ⚠ **So an adjustment for it assumes the firm will never again do the thing it is asking the bank to fund**, **which is an argument against the application and not an adjustment.**'));
out.push(p('**3**  ⚠ **No restatement of 2023 for a stock-valuation change, because there was none.** ⚠ **And no annualising of the four months of 2026** — **four months of a seasonal trade multiplied by three is a figure that means nothing** — **with the four months at appendix 5 as four months, in case the committee wants them.**'));
out.push(stage('6', 'Write with help – sample (152 words)'));
out.push(sample(null, [
  '**THE FOUR ADJUSTMENTS, AND THE TWO I HAVE NOT MADE. 16 May. L. Barakat. Working note.**',
  '**the two special journeys, 190 cartons** | ⚠ **yes** — **the Homs store closed in 2021** | ⚠ **yes** — **no stock left** | ⚠ **removed, and declared: five per cent becomes seven**',
  '**the February van failure** | ⚠ **no** — **we hire nine times a year** | ⚠ **no** | ⚠ **kept, and given twice: with it 3,140 and without it about 3,200**',
  '**the August fuel price** | ⚠ **no** | ⚠ **no** — **that is a frequency** | ⚠ **kept, and explained in one sentence**',
  '**the holiday week each November** | ⚠ **yes** — **it has passed** | ⚠ **no** — **there is one every year** | ⚠ **kept, and named as the cause of the November figure**',
  '⚠ **Three of the four fail the test and one passes, which is the normal proportion.** ⚠ **The two questions exist to stop a writer removing the items that happen to be inconvenient.**',
  '⚠ **The fourth row passes the first question and fails the second**, **which is the shape to watch for: a reason that has gone and will come back.**',
  '⚠ **And the adjustments I have NOT made: no reweighting for the heavier export cartons, because the series is cartons and not weight.**',
]));
out.push(stage('6P', 'Check together – sample completed checklist'));
out.push(table(['Checklist', '✓ / ✗'], [
  ['Both questions applied to every item, not only the removed ones', '**✓** — **all four rows carry both**'],
  ['The proportion that failed the test, stated', '**✓**'],
  ['A removal declared, with both figures given', '**✓** — **five and seven**'],
  ['A frequency kept, and named as a frequency', '**✓** — **row 3**'],
  ['The adjustments not made, with reasons', '⚠ **✓** — **one of them, where the unit\'s model gives two; one with a reason beats two without**'],
], [5, 1]));
out.push(note('A clean sheet here, which is rarer than it looks, and the thing to praise specifically is the fourth row: a reason that has gone and will come back. That shape — the November holiday, a new counter filling, a contract ending that will be replaced — is where every argument about adjustments actually happens, and a learner who has written one has understood that the two questions are not a formality. Where a class has produced only the easy rows, give them the Baghdad Street row from the unit and make them decide it. Expect disagreement, and let it run: the point is not the verdict but that the verdict needs both questions and a view about what the company intends to do next.'));
out.push(stage('6R', 'Share'));
out.push(p('⚠ **The class applies the two questions to the removed item** — **and where the second answer is *it might*, the item goes back in.** ⚠ **_It might_ is the answer to watch for: it is how a frequency presents itself to the person who wants to remove it.**'));
out.push(stage('7', 'Write freely – sample (233 words)'));
out.push(sample(null, [
  'The wastage figure the store reports every month has had the January scrap taken out of it since 2022, and nobody who takes it out now knows who decided to.',
  'What was taken out of what: the nine scrap cartons of January, which are in the fourth store, come out of the monthly wastage rate. The rate is reported as 1.1 per cent. With the January cartons in it, the year runs at about 1.3.',
  'Who took it out is not recorded. It appears first in the February 2022 sheet, in a hand I do not recognise, with the words "excl. Jan scrap" in the margin, and every sheet since has done the same thing without the note.',
  'Was it a one-off or a frequency: a frequency. We have scrapped stock in January in each of the last four years, because January is when the store is counted and the damaged cartons are found. It happens annually, which is the definition of a thing that recurs.',
  'Who found out and when: I did, three weeks ago, and only because the 2022 sheet is the one with the margin note on it.',
  'And what the undeclared version has been used to argue is that wastage is under control at 1.1 per cent, which was in the insurance renewal and in the paper that got the fourth store its shelving.',
]));
out.push(stage('7P', 'Respond'));
out.push(p('⚠ **The *one-off or frequency* question is answered *frequency* in most texts, and the sample shows why the undeclared version is the dangerous one: an adjustment nobody declared cannot be withdrawn, because there is no document to withdraw it from.** ⚠ **Note also that the sample\'s figure went into two outside documents** — **an insurance renewal and a capital paper** — **which is the normal fate of a flattering undeclared adjustment.**'));
out.push(stage('7R', 'Share'));
out.push(p('⚠ **Expect the item to be a frequency in two of three, and the adjusted figure still to be in use.** ⚠ **The sentence to close on: an adjustment that was never declared cannot be withdrawn, because there is nothing to withdraw it from** — **and that is the whole argument for declaring the ones that flatter you.**'));

// ===================== 8.5 =====================
out.push(pb());
out.push(h2('8.5  The round number and the spurious precision'));
out.push(stage('1', 'Get ready'));
out.push(p('**a**  Open. ⚠ **The gap between the two answers is the cycle.** **Most learners quote to the precision their spreadsheet produced**, **which is a precision nobody chose and which belongs to the arithmetic rather than to the measurement.**'));
out.push(p('**b**  ⚠ **The first.** ⚠ **173.6 is fifteen per cent applied to an audited figure: the 148.2 is measured and the fifteen per cent is a guess, so the point six belongs to neither.** ⚠ **_About 170_ claims exactly what is known.**'));
out.push(stage('2', 'Listen and read'));
out.push(p('**a**  B   **b**  1 ⚠ **Actuals to the nearest hundred thousand, with the same rounding in every document; forecasts to the nearest ten million, with *about* in front.**  2 ⚠ **Forty million exactly, with no *about* and no *approximately*** — **it is not an estimate, it is a request.**'));
out.push(p('⚠ **The sentence to put on the board is Mr Ayoub\'s and it is the rule for the whole cycle:** ⚠ **precision is a claim about method, and the claim has to be true.** **Every decision in the appendix follows from it** — **the decimal that stays on an audited actual, the decimal that comes off a forecast, the tenth of a debtor day that was never measured.**'));
out.push(p('⚠ **The request is the part learners get wrong in the opposite direction and it matters commercially.** ⚠ **_About forty million_ concedes that the number is negotiable before anybody has negotiated** — **and Mr Ayoub\'s sentence is the one to quote: a man asking for about forty million has not decided what he needs, and the committee will decide for him.**'));
out.push(p('⚠ **And the debtor-day decimal is the small one that teaches the general case.** ⚠ **A tenth of a day is eight hours and nobody measures receivables to eight hours**, **so 58.1 does not make the figure more accurate** — ⚠ **it makes the reader wonder what else has been dressed up, which is a cost paid on every other figure on the page.**'));
out.push(p('**Language box – Practise (sample, four kinds):**  _**an actual:** 3,140 cartons, as counted on the run sheets. **a ratio:** 7 cartons a delivery, not 6.9 — ⚠ **nobody delivers a tenth of a carton.** **a forecast:** ⚠ *about 3,300 cartons next year*, not 3,297. **a request:** ⚠ **two more pallets of racking, exactly, with no *about*.**_'));
out.push(stage('3', 'Practise – sample with role card 1'));
out.push(dlg(null, [
  ['A', 'We expect 3,297 cartons next year.'],
  ['B', 'Where did the 297 come from?'],
  ['A', 'Five per cent on this year\'s 3,140.'],
  ['B', 'And which part of that is measured?'],
  ['A', 'The 3,140. The five per cent is the three-year rate.'],
  ['B', 'Which is a rate from the past applied to the future. So what is the 297?'],
  ['A', 'Arithmetic on a guess.'],
  ['B', 'Say it again.'],
  ['A', 'About 3,300.'],
  ['B', 'Which is shorter, true, and the only version a reader can do nothing with except believe.'],
]));
out.push(note('The question that does the work is "which part of that is measured?" — and it is worth drilling because it transfers. A forecast is almost always a measured figure multiplied by an unmeasured one, and the product inherits the precision of the worse factor, not the better. Learners arrive believing that more digits are more careful; they leave understanding that a digit is a claim. The reliable way to show it is to ask for the forecast\'s error: if a learner cannot say whether their forecast could be out by five per cent, they cannot defend a tenth of a per cent of it, and that is the whole argument in two questions.'));
out.push(stage('3R', 'Perform'));
out.push(p('**Listener task:** ⚠ **The four kinds of figure and the precision each takes, and which of the speaker\'s figures was dressed.** ⚠ **The tell is a decimal on a product: where two numbers have been multiplied and one of them was a guess, the decimal belongs to the arithmetic and not to the world.**'));
out.push(stage('4', 'Your turn – sample table'));
out.push(table(['The figure', 'Actual · forecast · request · ratio', 'The precision I will use', 'The rule I used'], [
  ['**3,140 cartons**', '**actual**', '**as counted**', '⚠ **an actual keeps its measurement**'],
  ['**7 cartons a delivery**', '**ratio**', '⚠ **whole numbers**', '⚠ **nobody delivers a tenth of a carton**'],
  ['**about 3,300 next year**', '**forecast**', '⚠ **nearest hundred, with *about***', '⚠ **a rate from the past times an actual is a guess**'],
  ['**two pallets of racking**', '**request**', '⚠ **exact, no hedge**', '⚠ ***about two* invites one**'],
], [1.6, 1.6, 1.6, 1.8]));
out.push(stage('4R', 'Report – sample'));
out.push(p('_**The figure is next year\'s cartons. It is a forecast, so it goes to the nearest hundred with *about* in front. The rule is that a rate from the past applied to a measured figure is a guess, and a guess does not acquire precision by being multiplied. And the one I had dressed up was 3,297.**_'));
out.push(p('⚠ **The second listener count is the commercial one.** **How many requests carried the word *about*: usually most of them** — ⚠ **and the thing to name is what the word concedes.** **It does not soften the ask; it transfers the decision.**'));
out.push(stage('5', 'Read'));
out.push(p('**1**  ⚠ **Because the same figure appeared as 148.2 in one draft and 148 in another, and both drafts had gone out.** ⚠ **The conventions exist to stop 8.1\'s fault recurring**, **and a convention with the fault that produced it attached is followed, where a bare style note is not.**'));
out.push(p('**2**  ⚠ **The percentage line, which keeps one decimal.** ⚠ **The margin moved 1.6 points across three years, so the decimal is the difference between 20.1 and 19.8** — **and a table of margins rounded to whole numbers would print 21, 20, 20 and hide the recovery entirely.**'));
out.push(p('**3**  ⚠ **That it is a request and not an estimate**, ⚠ **and that *about* concedes the number is negotiable before anybody has negotiated** — **Mr Ayoub\'s sentence: a man asking for about forty million has not decided what he needs, and the committee will decide for him.**'));
out.push(stage('6', 'Write with help – sample (148 words)'));
out.push(sample(null, [
  '**ROUNDING AND PRECISION IN THE RUN PAPERS. 18 May. L. Barakat. The conventions.**',
  '⚠ **This note exists because the cartons figure went out as 3,140 in one report and 3,141 in another, and the second was a corrected run sheet nobody had told the first about.**',
  '**a counted actual** | ⚠ **as counted, whole cartons** | **3,140** | ⚠ **it is a count and a count has no decimal**',
  '**a ratio** | ⚠ **whole numbers** | **7 cartons a delivery** | ⚠ **nobody delivers a tenth of a carton**',
  '**a forecast** | ⚠ **nearest hundred, with *about*** | ⚠ ***about 3,300*** | ⚠ **a past rate times an actual is a guess**',
  '**the amount requested** | ⚠ **exact, no hedge** | ⚠ **two pallets of racking** | ⚠ **it is a request and not an estimate**',
  '⚠ **The one line that will be argued with is the forecast.** **The budget form has a box for a number and no room for a word** — ⚠ **and we are writing *about 3,300* across it, and anybody who wants a single number can ask and will get the method.**',
]));
out.push(stage('6P', 'Check together – sample completed checklist'));
out.push(table(['Checklist', '✓ / ✗'], [
  ['The fault that produced the conventions, named', '⚠ **✓** — **and it is a better fault than the unit\'s, because the two figures were both right on different days**'],
  ['Precision decided by the kind of figure, not its size', '**✓**'],
  ['A decimal kept where it is doing work', '⚠ **✗** — **no line in this note keeps a decimal at all, so the principle is untested**'],
  ['The line a reader will argue with, named first', '**✓** — **the forecast, and the box on the form**'],
  ['The request exact, in every place it appears', '**✓**'],
], [5, 1]));
out.push(note('The third line is a real failure and not a pedantic one. A set of conventions in which every rule removes precision has not been tested against the case where precision earns its place, and a learner who has written only rounding rules will round the one figure that needed its decimal — a margin, a defect rate, a yield. The repair is one line: find a figure in your own work that moves within a point, and write the rule that keeps its decimal. The unit\'s own example is the margin at 21.4, 19.8, 20.1, where whole numbers would print 21, 20, 20 and delete the recovery.'));
out.push(stage('6R', 'Share'));
out.push(p('⚠ **The class asks which part of the forecast was measured** — **and where any part of it is, that part keeps its precision and the product does not.** ⚠ **A forecast built from a firm order book is the interesting case: the ordered part is an actual and the rest is a guess, and the two should be given separately rather than added and rounded.**'));
out.push(stage('7', 'Write freely – sample (231 words)'));
out.push(sample(null, [
  'The yard reports a loading time of 2.4 minutes a pallet, and it is one of the most precise-looking numbers in this company and one of the least known.',
  'Where it comes from is a single morning in 2021. Somebody stood in the yard with a watch for about two hours, timed what I believe was eleven pallets, and divided. The 2.4 is eleven observations on one morning in one season with one driver.',
  'It is quoted to one decimal place everywhere: in the loading schedule, in the paper that justified the second forklift, and in the figure we give customers for how long a collection takes.',
  'The precision it deserves is none of those. Eleven observations will not support a tenth of a minute. They will support "about two and a half minutes", and they will not support a claim about February, or about a pallet of tiles against a pallet of dried goods, because all eleven were one line of goods.',
  'What the extra digit has been used to suggest is that loading is measured. It is not measured, it was measured once, and the difference between those two things is four years and about nine hundred working days.',
  'What it would take to deserve the decimal is a week of timings across two seasons, which is one person for perhaps three hours in total, and nobody has done it because the figure has never been questioned.',
]));
out.push(stage('7P', 'Respond'));
out.push(p('⚠ **The *which part of it was measured* question produces the sample\'s best line** — **it is not measured, it was measured once, and the difference is four years** — ⚠ **and that distinction between a measurement and a measurement\'s anniversary is worth naming, because almost every over-precise operational figure in a company is of that kind.**'));
out.push(stage('7R', 'Share'));
out.push(p('⚠ **Expect the over-precise figure to be a forecast, a target or a one-off measurement in all three, and in two of three the precision to have been inherited from a spreadsheet nobody chose.** ⚠ **The sentence to close on: a digit is a claim about method, and most spurious digits were never claimed by anybody** — **they were simply never removed.**'));

// ===================== 8.6 =====================
out.push(pb());
out.push(h2('8.6  The figure the reader will check'));
out.push(stage('1', 'Get ready'));
out.push(p('**a**  Open. ⚠ **Most learners cannot name the reader\'s own document, which is the cycle\'s subject:** **a customer has your invoices, a bank has your statement, an auditor has your ledger, a tax office has your returns** — **and each of them shows the same trade measured a different way.**'));
out.push(p('**b**  ⚠ **The second.** **The bank already has the lodgements, because the account is with it.** ⚠ **It does not have your sales figure and it will compare the two whether you help it or not.**'));
out.push(stage('2', 'Listen and read'));
out.push(p('**a**  B   **b**  1 ⚠ **Receivables rose 5.3 million over the year, and 4.5 million of the Beirut customers pay into the Beirut account** — **5.3 and 4.5 is 9.8.**  2 ⚠ **A difference the reader finds first is a question about you; a difference you hand him with its arithmetic is a demonstration that you read your own statements.**'));
out.push(p('⚠ **The whole cycle turns on one question and it should be asked of the class before the track is played:** ⚠ **what does the reader already have?** **A bank with your account has three years of your statement, and no learner in the series\' own trial thought of it unprompted.**'));
out.push(p('⚠ **The bridge that adds exactly is the strongest four lines available in any paper of figures, and the reason is worth stating plainly:** ⚠ **it demonstrates that two independently kept records agree**, **which no amount of prose can do.** ⚠ **The six words *the difference is accounted for in full* are only available to a writer whose arithmetic adds** — **which is why they carry weight.**'));
out.push(p('⚠ **And the Beirut account is the cycle\'s hard case.** ⚠ **4.5 million of receipts going to another bank is already visible to this one as an absence.** **Handed over with its arithmetic it is evidence of competence; found by the committee it is a question about why it was not mentioned** — **and the second conversation is not about banking arrangements.**'));
out.push(p('**Language box – Practise (sample):**  _**My figure:** 3,140 cartons carried. **The reader\'s own record:** the two Ghouta customers\' goods-received books, which show 2,980 between them. ⚠ **The gap:** 160. ⚠ **The bridge:** 104 cartons delivered to the third customer, who is not one of the two, and 56 cartons returned damaged and re-delivered in the following month, counted once by us and twice by nobody. ⚠ **104 and 56 is 160, and the difference is accounted for in full.**_'));
out.push(stage('3', 'Practise – sample with role card 2'));
out.push(dlg(null, [
  ['A', 'I would rather not put the Beirut account in the paper.'],
  ['B', 'What can they see on their own statement?'],
  ['A', 'The sweeps. They come in weekly as transfers from Beirut.'],
  ['B', 'So they can see money arriving from an account they do not hold.'],
  ['A', 'Yes. And they can see that it is not arriving as lodgements.'],
  ['B', 'Which means the 4.5 million is on their statement twice, once as a sweep and once as a hole.'],
  ['A', 'Put like that it sounds worse than it is.'],
  ['B', 'It is not worse than it is. It is four days of Lebanese clearing and it is swept weekly. The only question is whether they read that from you or work it out from their own records.'],
  ['A', 'And if they work it out?'],
  ['B', 'Then the next question is not about Beirut.'],
]));
out.push(note('That last exchange is the one to read aloud, because it names the real cost. Nothing in the Beirut arrangement is wrong — it exists because two export customers pay in Lebanese banking hours and a Damascus clearing added four days, and the account is swept weekly and holds nothing. The risk is not the arrangement but the order of discovery. A reader who finds an unexplained flow of money asks a question about the writer, not about the flow, and no subsequent explanation retrieves the first question. Learners find this easier to accept in the second person: ask what they would think if a supplier\'s figures showed money they could see going somewhere else and the supplier had not mentioned it.'));
out.push(stage('3R', 'Perform'));
out.push(p('**Listener task:** ⚠ **The two figures, the gap, the items, and the arithmetic checked by the listener.** ⚠ **Where it adds, the listener should say the six words aloud** — **and where it does not, the remainder is named rather than absorbed, which is the discipline the cycle exists for.**'));
out.push(stage('4', 'Your turn – sample table'));
out.push(table(['My figure', 'The document the reader has', 'His figure and the gap', 'The bridge — does it add?'], [
  ['**3,140 cartons carried**', '⚠ **the two customers\' goods-received books**', '**2,980 — a gap of 160**', '⚠ **104 to the third customer + 56 re-delivered = 160.** **Yes.**'],
  ['**49 piastres a carton**', '⚠ **the yard\'s own cost sheet**', '**41 — a gap of 8**', '⚠ **van hire, 8 piastres a carton spread over the year.** **Yes.**'],
  ['**102 deliveries in 2025**', '⚠ **the day book**', '**106 — a gap of 4**', '⚠ **4 special journeys, which are not scheduled runs.** **Yes, and the basis differs rather than the count.**'],
], [1.4, 1.8, 1.6, 1.8]));
out.push(stage('4R', 'Report – sample'));
out.push(p('_**My figure is 3,140 cartons. The reader already has the goods-received books, which show 2,980. His figure is 2,980, so the gap is 160. The bridge is 104 cartons to the third customer and 56 re-delivered after damage, which adds to 160.**_'));
out.push(p('⚠ **The remainder is the teaching in this stage.** **How many bridges added at the first attempt: usually one or two of three.** ⚠ **And what the remainder turned out to be in the others: in the series\' own trial it was a real thing nobody had noticed every single time** — **a credit note, a return, a delivery counted in two months.** **A bridge that does not add has found something.**'));
out.push(stage('5', 'Read'));
out.push(p('**1**  ⚠ **It was opened in May 2024 because the two export customers pay in Lebanese banking hours and a Damascus clearing added four days to every receipt.** **It holds nothing and is swept to the bank weekly.** ⚠ **So the 4.5 million is on the bank\'s own statement twice** — **once as a sweep under *transfer, Beirut*, and once as an absence from the lodgements** — **which is the sort of thing a committee finds in nine minutes and remembers for nine years.**'));
out.push(p('**2**  ⚠ **Because the difference and the receivables movement are both 3.5, which looks arranged.** ⚠ **The real figures are 3.52 and 3.47.** ⚠ **She left both at 3.5 because the convention is one decimal and changing the convention for one cell to avoid looking neat would be worse than looking neat** — **which is 8.5 applied against her own interest.**'));
out.push(p('**3**  ⚠ **That the gap proves the collection is weakening.** ⚠ **Lodgements rose more slowly than sales in both years, which is what any growing book with a lengthening period does arithmetically** — **and the whole of the lengthening is the two export accounts on sixty-day terms, printed twice at 46/51/58 and 46/47/48.** **The gap is arithmetic and not a finding.**'));
out.push(stage('6', 'Write with help – sample (150 words)'));
out.push(sample(null, [
  '**CARTONS CARRIED AND CARTONS RECEIVED: THE BRIDGE. 20 May. L. Barakat. Appendix 1.**',
  '⚠ **The two Ghouta customers keep goods-received books and will compare them with our run figures. The two do not match and are not meant to. This appendix is the arithmetic.**',
  '**our cartons carried** | **2,760** | **2,940** | **3,140**',
  '**their books, the two customers** | **2,656** | **2,810** | **2,980**',
  '⚠ **difference** | **104** | **130** | **160**',
  '**delivered to the third customer, not in their books** | **104** | **104** | **104**',
  '⚠ **damaged and re-delivered the following month** | ⚠ **nil** | **26** | **56**',
  '⚠ **bridge total** | ⚠ **104** | ⚠ **130** | ⚠ **160**',
  '⚠ **The difference is accounted for in full in all three years.** **There is no balancing item and no line called *other*.**',
  '⚠ **On the re-deliveries, which they can see:** **a carton re-delivered appears once in our run figure and twice in theirs, in two different months** — **and that is what makes their December figure lower than ours every year.**',
]));
out.push(stage('6P', 'Check together – sample completed checklist'));
out.push(table(['Checklist', '✓ / ✗'], [
  ['The reader\'s own figure named, beside yours', '**✓**'],
  ['A bridge for every period, not only the latest', '**✓** — **three years, all adding**'],
  ['No *other* line and no balancing item', '**✓**'],
  ['The uncomfortable item explained, including the worse part', '⚠ **✓** — **the re-delivery counted twice in their books, which is a point against our own record-keeping**'],
  ['A conclusion the bridge seems to offer, refused', '⚠ **✗** — **the bridge invites *their books understate us*, and the sample does not refuse it**'],
], [5, 1]));
out.push(note('The fifth line fails in most of the class\'s work and it is the hardest of the five, because refusing a conclusion your own arithmetic appears to support is the opposite of what writing figures feels like. Give them the words: a difference that is accounted for in full supports no conclusion about either party, because both records are correct on their own basis. In the sample, their books do not understate anything — they record what arrived at their doors, which is what a goods-received book is for. The sentence to add is one line: both records are right and the difference is a difference of basis.'));
out.push(stage('6R', 'Share'));
out.push(p('⚠ **The class does the arithmetic aloud, and where it does not add the missing amount is named.** ⚠ **The temptation is a line called *other* or *timing*, and both are gaps with names on them** — **and a reader goes straight to the line called *other*, every time.**'));
out.push(stage('7', 'Write freely – sample (228 words)'));
out.push(sample(null, [
  'In March a customer\'s accounts clerk telephoned to say that our statement and her ledger were 340,000 apart, and she had found it before I had ever compared the two.',
  'The two documents were our statement of account, which we send monthly, and her purchase ledger, which I had never seen.',
  'The difference was 340,000, and she had the figure to the piastre when she rang.',
  'The explanation turned out to be two things and both were innocent. A credit note we had raised in February had been dated February and allocated in March, so it was in different months on the two records. And one delivery had been invoiced twice and the second invoice cancelled, and the cancellation was on our ledger and had never been sent to her, so her ledger carried an invoice we no longer had.',
  'What it cost to explain second rather than first was eleven days. Eleven days of letters, two telephone calls with her manager, and a fortnight in which our account was not paid at all, on 1.4 million that was not in dispute.',
  'And the whole of it was avoidable by one column. If the statement we send had carried her ledger reference against each line, as her own statements to her customers do, neither of the two differences could have survived a month, and nobody would have had to telephone anybody.',
]));
out.push(stage('7P', 'Respond'));
out.push(p('⚠ **The *was the explanation innocent* question is answered yes in nearly every text**, **which is the finding of the stage:** ⚠ **the cost of a reconciliation you did not do first is almost never the money and almost always the fortnight spent proving there was nothing in it.**'));
out.push(stage('7R', 'Share'));
out.push(p('⚠ **Expect all three explanations to be innocent, and all three costs to be time rather than money.** ⚠ **The sentence to close on: the question is never whether the two records will be reconciled** — **somebody always does it** — **it is only whether you do it first, in a document, or second, on a telephone.**'));

// ===================== 8.7 =====================
out.push(pb());
out.push(h2('8.7  Review & Mediate: the figure Mr Haddad will ask for'));
out.push(stage('1', 'Get ready – Unit 8 quiz'));
out.push(p('**1** ⚠ **Its period, its basis, and its source with a page** — **and *last year* is not a period.**'));
out.push(p('**2** ⚠ **Four points.** **Three years give you two steps, which are two observations and not a direction.**'));
out.push(p('**3** ⚠ **A movement in a quantity is in per cent; a movement in a percentage is in percentage points.** **The margin fell 1.6 points, not 1.6 per cent.**'));
out.push(p('**4** ⚠ **Did it happen for a reason that has gone, and will it not happen again?** **Both.** ⚠ **A frequency fails the second** — **a press nine years old that has broken twice will break again.**'));
out.push(p('**5** ⚠ **A forecast is rounded and takes *about*; a request is exact and takes no hedge at all.**'));
out.push(p('**6** ⚠ **A bridge is the items that make up the difference between your figure and the reader\'s own record of the same trade, adding exactly.** ⚠ **The sentence is *the difference is accounted for in full*, and it is only available if the arithmetic adds.**'));
out.push(stage('2', 'Listen and read'));
out.push(p('**a**  B   **b**  1 ⚠ **Sixty-one at the end of April, on the same basis as the paper** — **three days worse than the 58 at December.**  2 ⚠ **Because he could have calculated it himself from the aged list that was attached.** ⚠ **He asked in order to find out whether she would tell him the worse number on a telephone without a pause.**'));
out.push(p('⚠ **This track is the end of Book 1\'s first argument and it should be taught as such.** **Seven units have been about what goes in a document.** ⚠ **This one says what the document was for: a paper exists to make a telephone call possible, not to replace it** — **and the four seconds before an answer is the part of a facility application that cannot be written.**'));
out.push(p('⚠ **The four-part answer is the mechanics and should be drilled in order.** ⚠ **The figure, with no preface · the basis, in one clause · the comparison, in the direction against you · the cause, with two earlier periods.** ⚠ **Reversing the first two is the commonest fault and it is fatal**, **because a basis stated before a bad number is heard as a preface, and a preface is heard as a reason prepared in advance.**'));
out.push(p('⚠ **And the last part is the one that shows a class has understood Unit 8 rather than memorised it.** ⚠ **Three Aprils is three points, and 8.2 forbids calling three points a pattern** — **so the writer declines to call it a seasonal pattern and names the appendix and the page instead, and lets the committee call it what it likes.** ⚠ **Declining to draw the conclusion while handing over the data is the most sophisticated move in Book 1**, **and it is available only to somebody who has the data.**'));
out.push(p('**Language box – Practise (sample):**  _The question I would be asked: what is the cost a carton this month, not last year. ⚠ **The figure: 52 piastres.** ⚠ **The basis: the same as the paper, including hired vans.** ⚠ **The comparison: three piastres worse than the year\'s 49.** ⚠ **The cause: two hired vans in April, and April last year was 53 and the year before 50.** **And three Aprils is three points, so the three figures are at appendix 1, page 2.**_'));
out.push(stage('3', 'Practise – sample with pair 2'));
out.push(dlg(null, [
  ['Mr Ayoub', 'The paper is good. What is the cost a carton this month?'],
  ['Lina', 'Fifty-two piastres.'],
  ['Mr Ayoub', 'You did not look that up.'],
  ['Lina', 'I calculated it on Sunday. On the same basis as the paper, including hired vans.'],
  ['Mr Ayoub', 'And the paper says forty-nine.'],
  ['Lina', 'Three piastres worse. Two hired vans in April, and April last year was fifty-three and the year before fifty.'],
  ['Mr Ayoub', 'So April is always bad.'],
  ['Lina', 'Three Aprils is three points. I would not call it a pattern on three, but the three figures are at appendix 1, page 2.'],
  ['Mr Ayoub', 'You are not going to tell me what to think about them.'],
  ['Lina', 'No. You have the same three numbers I have.'],
]));
out.push(note('Pair 2 shows the move that learners find hardest to believe is allowed: handing over the data and declining to interpret it. It is not evasion and it should not sound like evasion — the test is that the writer has calculated the figure, knows the three years, and can say where they are to the page. What is being refused is only the word "pattern", and the refusal is principled because 8.2 established how many points a pattern needs. Where a learner does this well, point out that it is the opposite of the fault in 8.2\'s free writing, where one Saturday became a finding about Saturdays. The same discipline produces both the refusal to conclude and the willingness to hand over.'));
out.push(stage('3R', 'Perform'));
out.push(p('**Listener task:** ⚠ **The four parts in order, and the part where the speaker could have lost it.** ⚠ **The answer is almost always the first: a pause, a *well*, or a basis given before the figure** — **and all three are the same mistake, which is answering the question you prepared rather than the one asked.**'));
out.push(stage('4', 'Your turn – sample table'));
out.push(table(['The question I would be asked', 'The figure', 'Better or worse than the page?', 'The cause, and two earlier periods'], [
  ['**what is the cost a carton this month?**', '**52 piastres**', '⚠ **three worse than the 49 in the paper**', '⚠ **two hired vans in April; April 2024 was 53 and April 2023 was 50**'],
  ['**how many cartons this month?**', '**241**', '⚠ **better** — **the monthly average is 262 and April is normally low**', '⚠ **the holiday week; April 2024 was 236 and April 2023 was 228**'],
], [1.8, 1.1, 1.5, 2.1]));
out.push(stage('4R', 'Report – mediation'));
out.push(p('_**The question was the cost a carton this month. The figure is 52 piastres, which is three worse than the page. The cause is two hired vans in April, and the two earlier Aprils were 53 and 50.**_'));
out.push(p('⚠ **The word list reaches forty-eight items with this unit\'s six:** ⚠ **_a stated basis · a base year · a percentage point · a one-off item · a spurious precision · a bridge between two figures_.** **Collect them on the board under the forty-two from Units 1 to 7, and say that it runs to Unit 12 and to seventy-two.**'));
out.push(stage('5', 'Read – exam practice'));
out.push(p('⚠ **B2 Business Vantage Reading Part 4** — **multiple-choice cloze, fifteen gaps, four options each.** **The second Part 4 in this book.**'));
out.push(table(['Q', '1', '2', '3', '4', '5', '6', '7', '8'], [['Answer', 'B', 'A', 'C', 'B', 'B', 'C', 'A', 'C']], [1, 0.7, 0.7, 0.7, 0.7, 0.7, 0.7, 0.7, 0.7]));
out.push(table(['Q', '9', '10', '11', '12', '13', '14', '15'], [['Answer', 'D', 'B', 'C', 'A', 'D', 'B', 'C']], [1, 0.7, 0.7, 0.7, 0.7, 0.7, 0.7, 0.7]));
out.push(p('⚠ **Eight of the fifteen are fixed phrases and seven are grammar, and the examination technique is to do the grammar first** — **it is recoverable from the sentence, and a phrase is not.** ⚠ **The grammar gaps are 3 (*no time to assemble*), 6 (*which twelve months are meant*), 7 (*whose base has been lost*), 8 (*as though it were*), 11 (the imperative *Give*), 13 (*strip out*) and 14 (*whether… or not*).**'));
out.push(p('⚠ **Gap 9 is the one to teach from.** **Three of the four options collocate with something** — *carry a figure · hold a view · stand up to scrutiny* — ⚠ **and only *support* takes *precision* as its object.** **The instruction is to read the gap with its own noun and not with the noun you expect.** ⚠ **Gap 7 is the other trap: *which* is the answer candidates want and *whose* is the one the sentence needs, because the base belongs to the percentage.**'));
out.push(stage('6', 'Write with help – sample exam answer (129 words)'));
out.push(sample(null, [
  '**The figures**',
  'Turnover rose from 112.4 million in the year to 31 December 2023 to 148.2 million in the year to 31 December 2025, which is fifteen per cent a year compound. ⚠ **Excluding the clearance of the Homs stock in the base year, eighteen.**',
  '**The series that has moved against us**',
  '⚠ **Debtor days at 31 December were 46, 51 and 58, calculated on closing receivables over the year\'s sales.** The cause is the two export accounts opened in 2024, which pay at sixty days by agreement. ⚠ **Stripping out those two accounts, debtor days were 46, 47 and 48.**',
  '**What I recommend**',
  '⚠ **I recommend that we give the bank both series and the aged list, because the committee can calculate the first from the second in four minutes and will.**',
]));
out.push(p('⚠ **129 words, three headings, four content points, and four figures and no more** — **a direction with a rate, the adverse series, the adjustment, and the recommendation.** ⚠ **The recommendation is the part most candidates leave out of a Part 2 report**, **and it is the part the rubric asks for: *what I recommend* and not *what we might consider*.** ⚠ **Note also that every figure carries its period in the same clause**, **which is what 8.1 is for and what an examiner reads a report for.**'));
out.push(stage('6P', 'Check together – sample completed checklist'));
out.push(table(['Checklist', '✓ / ✗'], [
  ['Three headings, and nothing else by way of structure', '**✓**'],
  ['A direction with a rate, not a list of figures', '**✓**'],
  ['The series that moved against you, named by you', '⚠ **✓** — **and the heading itself names it, which is worth two marks of the rubric on its own**'],
  ['One adjustment, declared, with both figures', '⚠ **✓** — **two of them: the Homs clearance and the export accounts**'],
  ['A period on every figure — and 120 to 140 words', '**✓** — **129**'],
], [5, 1]));
out.push(note('Mark a Part 2 report for its headings before anything else, because they are the cheapest marks in the paper and the most often forgone. A report without headings is marked down for organisation however good the prose, and three headings cost six of the 140 words. The other thing to watch in marking is the word count going long rather than short: a candidate who has understood 8.1 wants to give every figure its period, its basis AND its source, and the source is the one to drop in a 140-word report. Period and basis stay; the page number belongs in the appendix nobody asked for.'));
out.push(stage('7', 'Write freely – sample (234 words)'));
out.push(sample(null, [
  'The reader is Mr Ayoub, and the figure he will ask for is not in the monthly run paper at all: he will ask what a carton costs us this month.',
  'The paper gives the year. Forty-nine piastres a carton for the year to December, including van hire, which is the basis the paper states.',
  'This month it is fifty-two. I calculated it on Sunday because it is the question I would ask if I were reading the paper, and it took about twenty minutes because the van invoices are not in the same file as the run sheets.',
  'Three piastres worse than the page, and the cause is two hired vans in April rather than one. April last year was fifty-three and the April before that was fifty, so April is always the worst month of the four I have figures for.',
  'What I would say first is the number. Fifty-two. Then that it is on the same basis as the paper, then that it is three worse, and then the two hired vans.',
  'What I would not say is that April is seasonally bad, because three Aprils is three points, and the unit is clear that a pattern needs four. The three figures are in the appendix with a page number and he can call it what he likes.',
  'And what I will not do is let him find the fifty-two somewhere else first.',
]));
out.push(p('⚠ **This is the sample to read aloud if only one is read, and the last line is why:** ⚠ ***what I will not do is let him find it somewhere else first*** — **which is Units 1 to 8 in thirteen words.**'));

// ===================== UNIT CHECK =====================
out.push(pb());
out.push(stage('✓', 'Unit 8 check'));
out.push(p('**A  Language — the answers.**'));
out.push(table(['**Q**', '1', '2', '3', '4', '5', '6', '7', '8'], [['Answer', 'b', 'c', 'a', 'b', 'b', 'c', 'a', 'c']], [1.2, 0.6, 0.6, 0.6, 0.6, 0.6, 0.6, 0.6, 0.6]));
out.push(p('⚠ **Q1 is *rose from X to Y*, which is the pattern of every three-year sentence in the unit** — **and *rose by* takes a difference, not an endpoint.** ⚠ **Q2 is the plural *points*, and it is worth asking why *per cents* is impossible: *per cent* is not a countable noun and the countable unit is the point, which is 8.3 in one word.** ⚠ **Q5 is the collocation *no record of*, tested again because Vantage Reading Part 4 tests exactly this and learners write *for* and *about*.** ⚠ **Q8 is the reduced relative** — *a figure quoted to one decimal* — **and 8.5 is the whole of it.**'));
out.push(p('**B  Listening (Track 8.15).**   **The figure asked for:** ⚠ **the debtor days today, not at the year end.**   **The figure given:** ⚠ **sixty-one.**   **How it compares with the paper:** ⚠ **three days worse** — **the paper says 58 at December.**   **The cause:** ⚠ **the two export accounts invoice in April and pay in June, so April and May are the worst two months of the year.**   **The two earlier Aprils:** ⚠ **sixty, and fifty-four.**   **Why it is not in the paper:** ⚠ **three Aprils is three points, and she would not call three points a pattern** — **the figures are at appendix 2, page 2.**   **What was actually being tested:** ⚠ **whether she would say the worse number on a telephone without a pause** — **he could have calculated it from the aged list himself.**'));
out.push(p('**C  Reading.**  ⚠ **The two items are the movement in receivables, 5.3 million, and the receipts paid into the Beirut account, 4.5 million.** ⚠ **They add to 9.8, which is exactly the difference between sales of 148.2 and lodgements of 138.4.** ⚠ **The sentence it allows is *the difference is accounted for in full*** — **six words that are available only to a writer whose bridge adds, and which demonstrate that two independently kept records agree.** **Give the mark for all three years if the learner noticed that the bridge adds in 2023 and 2024 as well, which is a different and stronger claim.**'));
